def mean(nums):
    """Return the average of a list of numbers."""
    return sum(nums) / len(nums)

alt:
def mean(nums):
    """Average of nums as a float (the list must not be empty)."""
    total = 0
    for n in nums:
        total += n
    return total / len(nums)
